from cardio_1 import a, G
# J69 — Pneumopathies d’inhalation et atteintes respiratoires toxiques (P-02-Pneumologie). Clés absentes du glossaire au 09.10.2026.
a('RADS', [('R', 'Reactive (réactive)'), ('A', 'Airways (des voies aériennes)'), ('D', 'Dysfunction (dysfonction)'), ('S', 'Syndrome')], 'Syndrome de dysfonction réactive des voies aériennes', '<p>Asthme sans période de latence, apparu dans les heures qui suivent une exposition unique et massive à un irritant inhalé (chlore, ammoniac, fumées), sans sensibilisation immunologique. Le terme a été forgé par Brooks en 1985 ; il désigne aujourd’hui la forme aiguë de l’asthme induit par les irritants (Suva, 2026).</p>', 'j69-rads')
a('CTCAE', [('C', 'Common (communs)'), ('T', 'Terminology (terminologie)'), ('C', 'Criteria for (critères de)'), ('A', 'Adverse (indésirables)'), ('E', 'Events (événements)')], 'Critères communs de terminologie des événements indésirables', '<p>Échelle de gravité des effets indésirables des traitements anticancéreux, publiée par l’Institut national du cancer des États-Unis (version 5.0, 2017). Elle cote la pneumopathie médicamenteuse ou radique de 1 (anomalie radiologique sans symptôme) à 5 (décès).</p>', 'j69-ctcae')
a('ESMO', [('E', 'European (européenne)'), ('S', 'Society for (société d’)'), ('M', 'Medical (médicale)'), ('O', 'Oncology (oncologie)')], 'Société européenne d’oncologie médicale', '<p>Société savante européenne d’oncologie. Sa revue <i>ESMO Open</i> a publié en 2022 l’avis d’experts de Conte et collaborateurs sur les pneumopathies interstitielles médicamenteuses des traitements anticancéreux.</p>')
a('ECHM', [('E', 'European (européen)'), ('C', 'Committee for (comité de)'), ('H', 'Hyperbaric (hyperbare)'), ('M', 'Medicine (médecine)')], 'Comité européen de médecine hyperbare', '<p>Comité qui fixe, par conférences de consensus, les indications européennes de l’oxygénothérapie hyperbare. La dixième conférence (avril 2016, publiée en 2017) recommande l’oxygène hyperbare dans l’intoxication au monoxyde de carbone avec trouble de conscience ou signe neurologique, cardiaque, respiratoire ou psychologique, et chez toute femme enceinte intoxiquée.</p>', 'j69-ohb')
